1|// hyp-1 direction (b) hardening (attempt-4): attempt-2 with ONE change:
2|// 256 threads per pair (8 simdgroups) instead of 128, doubling the 1-row
3|// grid from 512 to 1024 threads to fix occupancy starvation. Per-block
4|// numerics (qvm strided lanes + simd_sum, full-bf16 silu) bit-identical.
5|// Grid: rows*4 pairs x 256 threads.
6|uint pair = threadgroup_position_in_grid.x;
7|uint tid = thread_position_in_threadgroup.x;
8|uint simd = simdgroup_index_in_threadgroup;
9|uint lane = thread_index_in_simdgroup;
10|uint r = pair >> 2;
11|uint e = inds[pair];
12|
13|threadgroup bfloat tg_x[768];
14|threadgroup bfloat tg_gate[384];
15|threadgroup bfloat tg_up[384];
16|threadgroup bfloat tg_h[384];
17|
18|for (uint i = tid; i < 768u; i += 256u) {
19|  tg_x[i] = x[r * 768u + i];
20|}
21|threadgroup_barrier(metal::mem_flags::mem_threadgroup);
22|
23|ulong eW = (ulong)e * 36864ul;
24|ulong eS = (ulong)e * 9216ul;
25|float p[32];
26|
27|// gate: 12 blocks of 32 outputs in 2 waves of 8 simdgroups (4 idle in wave 2).
28|for (uint v = 0; v < 2u; ++v) {
29|  uint b = v * 8u + simd;
30|  if (b < 12u) {
31|    qvm_block(gate_w + eW, gate_scales + eS, gate_biases + eS, tg_x, 768u, 12u, 48u, b, b * 4u, lane, p);
32|    if (lane == 0) {
33|      for (uint j = 0; j < 32u; ++j) {
34|        tg_gate[b * 32u + j] = (bfloat)p[j];
35|      }
36|    }
37|  }
38|}
39|// up: same structure.
40|for (uint v = 0; v < 2u; ++v) {
41|  uint b = v * 8u + simd;
42|  if (b < 12u) {
43|    qvm_block(up_w + eW, up_scales + eS, up_biases + eS, tg_x, 768u, 12u, 48u, b, b * 4u, lane, p);
44|    if (lane == 0) {
45|      for (uint j = 0; j < 32u; ++j) {
46|        tg_up[b * 32u + j] = (bfloat)p[j];
47|      }
48|    }
49|  }
50|}
51|threadgroup_barrier(metal::mem_flags::mem_threadgroup);
52|
53|// silu-mul with MLX's Sigmoid lowering computed ENTIRELY in bf16: the
54|// compiled swiglu rounds after every op (proven by CPU search over all 64
55|// rounding placements: only full-bf16 matches the reference, bad=0).
56|for (uint t = tid; t < 384u; t += 256u) {
57|  float g = (float)tg_gate[t];
58|  bfloat e1 = (bfloat)metal::precise::exp(metal::abs(g));
59|  bfloat d = (bfloat)(1.0f + (float)e1);
60|  bfloat y = (bfloat)(1.0f / (float)d);
61|  bfloat s = (g < 0.0f) ? y : (bfloat)(1.0f - (float)y);
62|  bfloat p = (bfloat)(g * (float)s);
63|  tg_h[t] = (bfloat)((float)p * (float)tg_up[t]);
64|}
65|threadgroup_barrier(metal::mem_flags::mem_threadgroup);
66|
67|// down: 24 blocks of 32 outputs in 3 waves of 8 simdgroups.
68|for (uint v = 0; v < 3u; ++v) {
69|  uint b = v * 8u + simd;
70|  qvm_block(down_w + eW, down_scales + eS, down_biases + eS, tg_h, 384u, 24u, 96u, b, b * 4u, lane, p);
71|  if (lane == 0) {
72|    for (uint j = 0; j < 32u; ++j) {
73|      y[pair * 768u + b * 32u + j] = (bfloat)p[j];
74|    }
75|  }
76|}

