1|// Fused routing: router scores (matmul + sigmoid + bias), top-4 select, weight
2|// normalize/scale — one kernel launch per layer, one threadgroup (32 threads)
3|// per row. Grid is (rows*32, 1, 1), threadgroup (32, 1, 1).
4|//
5|// Per row: 60 experts, thread t computes experts t and (t+32 if t<28).
6|// x (768 bf16) is staged once into threadgroup memory; w_router rows are read
7|// straight from device memory. Thread 0 then does the serial top-4 scan over
8|// the 60 threadgroup scores, normalizes, and writes inds/weights.
9|
10|uint row = threadgroup_position_in_grid.x;
11|uint tid = thread_position_in_threadgroup.x;
12|
13|threadgroup float xsh[768];
14|threadgroup float scores[60];
15|
16|// Stage x[row] (bfloat -> float) cooperatively: 32 threads x 24 elements.
17|uint xbase = row * 768;
18|for (uint i = 0; i < 24; i++) {
19|  uint d = tid * 24 + i;
20|  xsh[d] = float(x[xbase + d]);
21|}
22|threadgroup_barrier(mem_flags::mem_threadgroup);
23|
24|// Two experts per thread (threads 0..27), one for threads 28..31.
25|for (uint k = 0; k < 2; k++) {
26|  uint e = tid + k * 32;
27|  if (e >= 60) {
28|    break;
29|  }
30|  uint wbase = e * 768;
31|  float acc = 0.0f;
32|  for (uint d = 0; d < 768; d++) {
33|    acc += xsh[d] * w_router[wbase + d];
34|  }
35|  scores[e] = 1.0f / (1.0f + metal::exp(-acc));
36|}
37|threadgroup_barrier(mem_flags::mem_threadgroup);
38|
39|if (tid == 0) {
40|  // Top-4 of biased scores, strictly-greater insertion (earliest index wins
41|  // ties; exact ties are G2-exempt near-tie rows).
42|  float topv[4] = {-INFINITY, -INFINITY, -INFINITY, -INFINITY};
43|  uint topi[4] = {0, 0, 0, 0};
44|  for (uint e = 0; e < 60; e++) {
45|    float b = scores[e] + bias[e];
46|    if (b > topv[0]) {
47|      topv[3] = topv[2]; topi[3] = topi[2];
48|      topv[2] = topv[1]; topi[2] = topi[1];
49|      topv[1] = topv[0]; topi[1] = topi[0];
50|      topv[0] = b; topi[0] = e;
51|    } else if (b > topv[1]) {
52|      topv[3] = topv[2]; topi[3] = topi[2];
53|      topv[2] = topv[1]; topi[2] = topi[1];
54|      topv[1] = b; topi[1] = e;
55|    } else if (b > topv[2]) {
56|      topv[3] = topv[2]; topi[3] = topi[2];
57|      topv[2] = b; topi[2] = e;
58|    } else if (b > topv[3]) {
59|      topv[3] = b; topi[3] = e;
60|    }
61|  }
62|  // Weights from the UNBIASED scores, same op order as the reference:
63|  // w / (sum + 1e-20) * 2.5.
64|  float s0 = scores[topi[0]];
65|  float s1 = scores[topi[1]];
66|  float s2 = scores[topi[2]];
67|  float s3 = scores[topi[3]];
68|  float denom = s0 + s1 + s2 + s3 + 1e-20f;
69|  uint obase = row * 4;
70|  inds[obase + 0] = topi[0];
71|  inds[obase + 1] = topi[1];
72|  inds[obase + 2] = topi[2];
73|  inds[obase + 3] = topi[3];
74|  weights[obase + 0] = (s0 / denom) * 2.5f;
75|  weights[obase + 1] = (s1 / denom) * 2.5f;
76|  weights[obase + 2] = (s2 / denom) * 2.5f;
77|  weights[obase + 3] = (s3 / denom) * 2.5f;
78|}

