1|// Bit-faithful replica of MLX affine_gather_qvm's per-output computation
2|// (quantized.h qvm_impl + qouter, bits=4 path) for one 32-output block:
3|// each lane accumulates its strided K elements serially, then a simd_sum tree
4|// reduces across the 32 lanes, exactly as the reference grid does.
5|inline void qvm_block(
6|    const device uint* W,
7|    const device bfloat* S,
8|    const device bfloat* B,
9|    const threadgroup bfloat* xv,
10|    uint K,
11|    uint G,
12|    uint Ww,
13|    uint g,
14|    uint wb,
15|    uint lane,
16|    thread float* p) {
17|  for (uint j = 0; j < 32u; ++j) {
18|    p[j] = 0.0f;
19|  }
20|  for (uint k = lane; k < K; k += 32u) {
21|    float x = (float)xv[k];
22|    float scale = (float)S[k * G + g];
23|    float bias = (float)B[k * G + g];
24|    float s0 = scale;
25|    float s1 = scale / 16.0f;
26|    ulong row = (ulong)k * (ulong)Ww + (ulong)wb;
27|    uint w4[4];
28|    for (uint j = 0; j < 4u; ++j) {
29|      w4[j] = W[row + j];
30|    }
31|    for (uint i = 0; i < 16u; ++i) {
32|      uint by = (w4[i >> 2] >> ((i & 3u) * 8u)) & 0xffu;
33|      p[2u * i] += x * (s0 * (float)(by & 0x0fu) + bias);
34|      p[2u * i + 1u] += x * (s1 * (float)(by & 0xf0u) + bias);
35|    }
36|  }
37|#pragma clang loop unroll(full)
38|  for (uint j = 0; j < 32u; ++j) {
39|    p[j] = simd_sum(p[j]);
40|  }
