164|template <typename T, typename U, typename Op, int N_READS = REDUCE_N_READS>
165|METAL_FUNC void
166|thread_reduce(thread U& total, const device T* row, int blocks, int extra) {
167|  Op op;
168|  for (int i = 0; i < blocks; i++) {
169|    U vals[N_READS];
170|    for (int j = 0; j < N_READS; j++) {
171|      vals[j] = row[j];
172|    }
173|    for (int j = 0; j < N_READS; j++) {
174|      total = op(vals[j], total);
175|    }
176|    row += N_READS;
177|  }
178|  for (int i = 0; i < extra; i++) {
179|    total = op(*row++, total);
180|  }
