337|inline U qdot_safe(
338|    const device uint8_t* w,
339|    const thread U* x_thread,
340|    U scale,
341|    U bias,
342|    U sum,
343|    int N) {
344|  static_assert(
345|      bits == 1 || bits == 2 || bits == 3 || bits == 4 || bits == 5 ||
346|          bits == 6 || bits == 8,
347|      "Template undefined for bits not in {1, 2, 3, 4, 5, 6, 8}");
348|
349|  U accum = 0;
350|
351|  if (bits == 1) {
352|    for (int i = 0; i < (N / 8); i++) {
353|      uint8_t wb = w[i];
354|      accum += select(U(0), x_thread[8 * i], bool(wb & 0x01));
355|      accum += select(U(0), x_thread[8 * i + 1], bool(wb & 0x02));
356|      accum += select(U(0), x_thread[8 * i + 2], bool(wb & 0x04));
357|      accum += select(U(0), x_thread[8 * i + 3], bool(wb & 0x08));
358|      accum += select(U(0), x_thread[8 * i + 4], bool(wb & 0x10));
359|      accum += select(U(0), x_thread[8 * i + 5], bool(wb & 0x20));
360|      accum += select(U(0), x_thread[8 * i + 6], bool(wb & 0x40));
361|      accum += select(U(0), x_thread[8 * i + 7], bool(wb & 0x80));
362|    }
363|  }
364|
365|  else if (bits == 2) {
366|    for (int i = 0; i < (N / 4); i++) {
367|      accum +=
368|          (x_thread[4 * i] * (w[i] & 0x03) +
369|           x_thread[4 * i + 1] * (w[i] & 0x0c) +
370|           x_thread[4 * i + 2] * (w[i] & 0x30) +
371|           x_thread[4 * i + 3] * (w[i] & 0xc0));
372|    }
373|  }
374|
375|  else if (bits == 3) {
376|    for (int i = 0; i < (N / 8); i++) {
377|      x_thread += 8 * i;
378|      w += 3 * i;
379|
380|      accum += (w[0] & 0x07) * x_thread[0];
381|      accum += (w[0] & 0x38) * x_thread[1];
382|      accum += (w[0] & 0xc0) * x_thread[2];
