201|template <int DIM, typename OffsetT = size_t, bool General = true>
202|struct LoopedElemToLoc {
203|  int dim;
204|  LoopedElemToLoc<DIM - 1, OffsetT, General> inner_looper;
205|  OffsetT offset{0};
206|  int index{0};
207|
208|  LoopedElemToLoc(int dim) thread : dim(dim), inner_looper(dim - 1) {}
209|
210|  void next(const constant int* shape, const constant int64_t* strides) thread {
211|    if (dim == 0) {
212|      return;
213|    }
214|    index++;
215|    offset += OffsetT(strides[dim - 1]);
216|    if (index >= shape[dim - 1]) {
217|      index = 0;
218|      inner_looper.next(shape, strides);
219|      offset = inner_looper.offset;
220|    }
221|  }
222|
223|  void next(int n, const constant int* shape, const constant int64_t* strides)
224|      thread {
225|    if (dim == 0) {
226|      return;
227|    }
228|    index += n;
229|    offset += n * OffsetT(strides[dim - 1]);
230|
231|    if (index >= shape[dim - 1]) {
232|      int extra = index - shape[dim - 1];
233|      if (extra >= shape[dim - 1]) {
234|        inner_looper.next(1 + extra / shape[dim - 1], shape, strides);
235|        extra = extra % shape[dim - 1];
236|      } else {
237|        inner_looper.next(shape, strides);
238|      }
239|      index = 0;
240|      offset = inner_looper.offset;
241|      if (extra > 0) {
242|        next(extra, shape, strides);
243|      }
244|    }
245|  }
246|
247|  OffsetT location() thread {
248|    return offset;
249|  }
250|};
