1222|template <typename T, const int group_size, const int bits>
1223|METAL_FUNC void qvm_impl(
1224|    const device uint32_t* w,
1225|    const device T* scales,
1226|    const device T* biases,
1227|    const device T* x,
1228|    device T* y,
1229|    const int in_vec_size,
1230|    const int out_vec_size,
1231|    const int in_vec_stride,
1232|    uint3 tid [[threadgroup_position_in_grid]],
1233|    uint simd_gid [[simdgroup_index_in_threadgroup]],
1234|    uint simd_lid [[thread_index_in_simdgroup]]) {
1235|  constexpr int power_of_2_bits = (bits & (bits - 1)) == 0;
1236|  constexpr int num_simdgroups = 2;
1237|  constexpr int pack_factor = get_pack_factor<bits, 32>();
