1243|  using W_T =
1244|      typename ConditionalType<power_of_2_bits, uint32_t, uint8_t>::type;
1245|  const device W_T* ws = (const device W_T*)w;
1246|
1247|  typedef float U;
1248|  typedef struct {
1249|    W_T wi[tn * bytes_per_pack];
1250|  } vec_w;
1251|
1252|  thread vec_w w_local;
1253|  thread U result[tn * pack_factor] = {0};
1254|  thread U scale = 1;
1255|  thread U bias = 0;
1256|  thread U x_local = 0;
1257|
1258|  // Adjust positions
1259|  const int out_vec_size_w = out_vec_size * bytes_per_pack / pack_factor;
1260|  const int out_vec_size_g = out_vec_size / group_size;
