1262|  ws += out_col * bytes_per_pack / pack_factor + simd_lid * out_vec_size_w;
1263|  scales += out_col / group_size + simd_lid * out_vec_size_g;
1264|  biases += out_col / group_size + simd_lid * out_vec_size_g;
1265|  x += tid.x * in_vec_stride + simd_lid;
1266|  y += tid.x * out_vec_size + out_col;
1267|
1268|  if (out_col >= out_vec_size) {
1269|    return;
1270|  }
1271|
1272|  // Loop over in_vec in blocks of block_size
1273|  int remaining = in_vec_size % block_size;
1274|  if (remaining == 0) {
1275|    for (int i = 0; i < in_vec_size; i += block_size) {
1276|      x_local = *x;
1277|      scale = *scales;
1278|      bias = *biases;
1279|      w_local = *((device vec_w*)ws);
1280|      qouter<U, tn * pack_factor, bits>(
1281|          (thread uint8_t*)&w_local, x_local, scale, bias, result);
1282|
1283|      x += block_size;
1284|      scales += block_size * out_vec_size_g;
1285|      biases += block_size * out_vec_size_g;
1286|      ws += block_size * out_vec_size_w;
1287|    }
1288|  } else {
1289|    for (int i = block_size; i < in_vec_size; i += block_size) {
1290|      x_local = *x;
1291|      scale = *scales;
1292|      bias = *biases;
1293|      w_local = *((device vec_w*)ws);
1294|
1295|      qouter<U, tn * pack_factor, bits>(
1296|          (thread uint8_t*)&w_local, x_local, scale, bias, result);
1297|
1298|      x += block_size;
1299|      scales += block_size * out_vec_size_g;
1300|      biases += block_size * out_vec_size_g;
1301|      ws += block_size * out_vec_size_w;
1302|    }
1303|    if (static_cast<int>(simd_lid) < remaining) {
1304|      x_local = *x;
1305|      scale = *scales;
1306|      bias = *biases;
1307|      w_local = *((device vec_w*)ws);
1308|    } else {
1309|      x_local = 0;
1310|      scale = 0;
1311|      bias = 0;
1312|    }
1313|    qouter<U, tn * pack_factor, bits>(
1314|        (thread uint8_t*)&w_local, x_local, scale, bias, result);
1315|  }
1316|
1317|// Accumulate in the simdgroup
1318|#pragma clang loop unroll(full)
1319|  for (int k = 0; k < tn * pack_factor; k++) {
1320|    result[k] = simd_sum(result[k]);
1321|  }
1322|
1323|  // Store the result
1324|  if (simd_lid == 0) {
1325|#pragma clang loop unroll(full)
1326|    for (int k = 0; k < tn * pack_factor; k++) {
1327|      y[k] = static_cast<T>(result[k]);
1328|    }
1329|  }
