453|struct BlockMMA {
454|  // MMAFrag size
455|  STEEL_CONST short kFragSize = 8;
456|  using MMAFrag_acc_t = BaseMMAFrag<AccumType, kFragSize, kFragSize>;
457|
458|  // Warp tile simdgroup matrix strides along M
459|  STEEL_CONST short TM_stride = kFragSize * WM;
460|  // Warp tile simdgroup matrix strides along M
461|  STEEL_CONST short TN_stride = kFragSize * WN;
462|
463|  // Warp tile size along M
464|  STEEL_CONST short TM = BM / (kFragSize * WM);
465|  // Warp tile size along N
466|  STEEL_CONST short TN = BN / (kFragSize * WN);
467|
468|  // Threadgroup A strides
469|  STEEL_CONST short A_str_m = transpose_a ? 1 : lda_tgp; // M
470|  STEEL_CONST short A_str_k = transpose_a ? lda_tgp : 1; // K
471|
472|  // Threadgroup B strides
473|  STEEL_CONST short B_str_k = transpose_b ? 1 : ldb_tgp; // K
474|  STEEL_CONST short B_str_n = transpose_b ? ldb_tgp : 1; // N
475|
476|  // Threadgroup strides along K
477|  STEEL_CONST short tile_stride_a = kFragSize * A_str_k;
478|  STEEL_CONST short tile_stride_b = kFragSize * B_str_k;
479|
480|  // Simdgroup matrices
481|  MMATile<AccumType, TM, 1, MMAFrag_acc_t> Atile;
482|  MMATile<AccumType, 1, TN, MMAFrag_acc_t> Btile;
483|  MMATile<AccumType, TM, TN, MMAFrag_acc_t> Ctile;
484|
485|  // Offsets within threadgroup
486|  short sm;
487|  short sn;
488|
489|  short As_offset;
490|  short Bs_offset;
491|
492|  /* Constructor */
493|  METAL_FUNC BlockMMA(
494|      ushort simd_group_id [[simdgroup_index_in_threadgroup]],
495|      ushort simd_lane_id [[thread_index_in_simdgroup]]) thread {
496|    // Determine thread position in simdgroup matrix
497|    short tm = kFragSize * (simd_group_id / WN);
498|    short tn = kFragSize * (simd_group_id % WN);
499|
500|    short2 simd_coord = MMAFrag_acc_t::get_coord(simd_lane_id);
501|    sm = simd_coord.y;
502|    sn = simd_coord.x;
503|
504|    // Determine thread and simdgroup offset
505|    As_offset = (tm + sm) * A_str_m + (sn)*A_str_k; // M, K
506|    Bs_offset = (sm)*B_str_k + (tn + sn) * B_str_n; // K, N
507|
508|    sm += tm;
509|    sn += tn;
510|  }
511|
512|  /* (BM, BK) X (BK, BN) multiply accumulate function */
513|  METAL_FUNC void mma(const threadgroup T* As, const threadgroup T* Bs) thread {
514|    // Adjust for simdgroup and thread location
515|    As += As_offset;
516|    Bs += Bs_offset;
517|
518|    // Iterate over BK in blocks of kFragSize
519|    STEEL_PRAGMA_UNROLL
520|    for (short kk = 0; kk < BK; kk += kFragSize) {
521|      simdgroup_barrier(mem_flags::mem_none);
522|
523|      Atile.template load<T, WM, 1, A_str_m, A_str_k>(As);
524|
525|      simdgroup_barrier(mem_flags::mem_none);
526|
527|      Btile.template load<T, 1, WN, B_str_k, B_str_n>(Bs);
528|
529|      simdgroup_barrier(mem_flags::mem_none);
530|
531|      tile_matmad(Ctile, Atile, Btile, Ctile);
532|
533|      // Progress to next simdgroup tile
534|      As += tile_stride_a;
535|      Bs += tile_stride_b;
536|    }
537|  }
