20|threadgroup uint Wtile[3072];
21|threadgroup bfloat Stile[768];
22|threadgroup bfloat Btile[768];
23|threadgroup bfloat xT[64];
24|threadgroup bfloat hbuf[2 * 384];
25|threadgroup uint nP;
