28|    uint e = threadgroup_position_in_grid.x;
29|    uint o = thread_position_in_threadgroup.x;
30|    int rows = x_shape[0];
31|    uint P = (uint)rows * 4u;
32|
33|    // Pair scan: one thread collects the (row, slot) codes routed to expert e.
34|    if (o == 0) {
35|        uint n = 0;
36|        for (uint t = 0; t < P; ++t) {
37|            if (inds[t] == e) {
38|                plist[n++] = t;
39|            }
40|        }
41|        nP = n;
42|    }
