1|// Kernel 1 of the two-kernel routing split: dense router matmul + sigmoid + bias.
2|// Grid: rows*60 threads, one per (row, expert). Threadgroup: 480 = 8 rows x 60.
3|// The k=768 reduction is tiled in chunks of 64 through threadgroup memory so the
4|// 184 KB router weight is read once per 8 rows instead of once per row.
5|// Every threadgroup covers whole rows (grid and group sizes are multiples of 60),
6|// so no bounds checks are needed.
7|threadgroup float w_tile[60 * 64];
8|threadgroup float x_tile[8 * 64];
9|
10|uint gid = thread_position_in_grid.x;
11|uint tid = thread_position_in_threadgroup.x;
12|uint r = gid / 60;
13|uint e = gid % 60;
14|uint lr = tid / 60;
15|
16|float acc = 0.0f;
17|for (uint k0 = 0; k0 < 768; k0 += 64) {
18|    // The first local row stages this expert's weight chunk.
19|    if (lr == 0) {
20|        uint wbase = e * 768 + k0;
21|        for (uint j = 0; j < 64; ++j) {
22|            w_tile[e * 64 + j] = w_router[wbase + j];
23|        }
24|    }
25|    // Thread e==0 of each local row stages its row's x chunk (exact bf16->f32).
26|    if (e == 0) {
27|        uint xbase = r * 768 + k0;
28|        for (uint j = 0; j < 64; ++j) {
29|            x_tile[lr * 64 + j] = float(x[xbase + j]);
30|        }
31|    }
32|    threadgroup_barrier(mem_flags::mem_threadgroup);
33|    for (uint j = 0; j < 64; ++j) {
34|        acc = fma(x_tile[lr * 64 + j], w_tile[e * 64 + j], acc);
35|    }
36|    threadgroup_barrier(mem_flags::mem_threadgroup);
37|}
38|
39|float s = 1.0f / (1.0f + metal::exp(-acc));
