    float part[32];
    for (uint pIdx = 0; pIdx < 32; pIdx++) {
      uint k_start = pIdx * 16;
      uint k_len = (pIdx == 31) ? 272 : 16;
      float p = 0.0f;
      for (uint d = k_start; d < k_start + k_len; d++) {
        p += xsh[d] * w_router[wbase + d];
