11|// x * (scale * q + bias), then a simd_sum tree reduces across lanes.
12|inline void qvm_block(
13|    const device uint* W,
14|    const device bfloat* S,
15|    const device bfloat* B,
16|    const threadgroup bfloat* xv,
17|    uint K,
18|    uint G,
19|    uint Ww,
20|    uint g,
21|    uint wb,
22|    uint lane,
23|    thread float* p) {
24|  for (uint j = 0; j < 32u; ++j) {
25|    p[j] = 0.0f;
26|  }
27|  for (uint k = lane; k < K; k += 32u) {
28|    float x = (float)xv[k];
29|    float scale = (float)S[k * G + g];
30|    float bias = (float)B[k * G + g];
31|    float s0 = scale;
32|    float s1 = scale / 16.0f;
33|    ulong row = (ulong)k * (ulong)Ww + (ulong)wb;
34|    uint w4[4];
35|    for (uint j = 0; j < 4u; ++j) {
36|      w4[j] = W[row + j];
37|    }
38|    for (uint i = 0; i < 16u; ++i) {
39|      uint by = (w4[i >> 2] >> ((i & 3u) * 8u)) & 0xffu;
40|      p[2u * i] += x * (s0 * (float)(by & 0x0fu) + bias);
41|      p[2u * i + 1u] += x * (s1 * (float)(by & 0xf0u) + bias);
42|    }
43|  }
