# compute candidate partitions for boundary-relevant rows
def cand(rows):
    if rows==1: return ("GEMV",)
    if rows<=768:
        tm=(rows+31)//32
        ratio=48//(tm*2)
        np_=1
        while np_<ratio: np_*=2
        if np_<2: np_=2
        part=min(np_,32)
        base=48//part
        if base==0: base=1
        # chunks per partition
        chunks=[]
        for p in range(part):
            c0=p*base; c1=48 if p+1==part else (p+1)*base
            chunks.append(c1-c0)
        return (f"splitK part={part} base={base} chunks={chunks} tm={tm} ratio={ratio}")
    return ("regular part=1 base=48",)
