126|  static METAL_FUNC void merge_step(
127|      const threadgroup ValT* As,
128|      const threadgroup ValT* Bs,
129|      const threadgroup IdxT* As_idx,
130|      const threadgroup IdxT* Bs_idx,
131|      short A_sz,
132|      short B_sz,
133|      thread ValT (&vals)[N_PER_THREAD],
134|      thread IdxT (&idxs)[N_PER_THREAD]) {
135|    CompareOp op;
136|    short a_idx = 0;
137|    short b_idx = 0;
138|
139|    for (int i = 0; i < N_PER_THREAD; ++i) {
140|      auto a = (a_idx < A_sz) ? As[a_idx] : ValT(CompareOp::init);
141|      auto b = (b_idx < B_sz) ? Bs[b_idx] : ValT(CompareOp::init);
