153|      b_idx += short(pred);
154|      a_idx += short(!pred);
155|    }
156|  }
157|
158|  static METAL_FUNC void sort(
159|      threadgroup ValT* tgp_vals [[threadgroup(0)]],
160|      threadgroup IdxT* tgp_idxs [[threadgroup(1)]],
161|      int size_sorted_axis,
162|      uint3 lid [[thread_position_in_threadgroup]]) {
163|    // Get thread location
164|    int idx = lid.x * N_PER_THREAD;
165|
166|    // Load from shared memory
167|    thread ValT thread_vals[N_PER_THREAD];
168|    thread IdxT thread_idxs[N_PER_THREAD];
169|    for (int i = 0; i < N_PER_THREAD; ++i) {
170|      thread_vals[i] = tgp_vals[idx + i];
171|      if (ARG_SORT) {
172|        thread_idxs[i] = tgp_idxs[idx + i];
173|      }
174|    }
175|
176|    // Per thread sort
177|    if (idx < size_sorted_axis) {
178|      thread_sort_t::sort(thread_vals, thread_idxs);
179|    }
180|
181|    // Do merges using threadgroup memory
182|    for (int merge_threads = 2; merge_threads <= BLOCK_THREADS;
183|         merge_threads *= 2) {
184|      // Update threadgroup memory
185|      threadgroup_barrier(mem_flags::mem_threadgroup);
186|      for (int i = 0; i < N_PER_THREAD; ++i) {
187|        tgp_vals[idx + i] = thread_vals[i];
188|        if (ARG_SORT) {
189|          tgp_idxs[idx + i] = thread_idxs[i];
190|        }
191|      }
192|      threadgroup_barrier(mem_flags::mem_threadgroup);
193|
194|      // Find location in merge step
195|      int merge_group = lid.x / merge_threads;
196|      int merge_lane = lid.x % merge_threads;
