201|      // As = tgp_vals[A_st:A_ed] is sorted
202|      // Bs = tgp_vals[B_st:B_ed] is sorted
203|      int A_st = sort_st;
204|      int A_ed = sort_st + sort_sz / 2;
205|      int B_st = sort_st + sort_sz / 2;
206|      int B_ed = sort_st + sort_sz;
207|
208|      const threadgroup ValT* As = tgp_vals + A_st;
209|      const threadgroup ValT* Bs = tgp_vals + B_st;
210|      int A_sz = A_ed - A_st;
211|      int B_sz = B_ed - B_st;
