49|// Weights are dequantized exactly as QuantizedBlockLoader/dequantize
50|// bits=4 does (quantized.h:617-623): (bfloat)(s*q + b) with
51|// sc = {s, s/16} on the byte nibbles, i.e. the dequantized weight is
52|// rounded to bfloat16 BEFORE the multiply. Accumulation follows
53|// BlockMMA (steel/gemm/mma.h:513-537) with BK=32: K tiles of 32 in
54|// increasing order, each tile four sequential 8-wide
55|// simdgroup_multiply_accumulate steps on float 8x8 fragments. This
56|// threadgroup holds a single row (row 0 of the fragment; rows 1-7
57|// are zero padding in separate accumulators, as schedule_row_tile's
58|// padded rows are in the reference), so per-row K order matches the
59|// reference while row grouping stays free. o32 receives the 32
60|// float accumulators; the caller rounds once to bfloat16.
61|inline void qmm_block(
62|    const device uint* W,
63|    const device bfloat* S,
64|    const device bfloat* B,
65|    const device bfloat* xv,
66|    uint Kdim,
67|    uint G,
68|    uint Ww,
69|    uint blk,
70|    uint lane,
71|    threadgroup float* Xs,
72|    threadgroup float* Ws,
73|    threadgroup float* tmp,
74|    thread float* o32) {
75|  simdgroup_matrix<float, 8, 8> acc[4];
76|  for (uint j = 0; j < 4u; ++j) {
77|    acc[j] = make_filled_simdgroup_matrix<float, 8>(0.0f);
78|  }
79|  for (uint kt = 0; kt < Kdim; kt += 32u) {
80|    for (uint i = lane; i < 256u; i += 32u) {
81|      uint row = i >> 5;
82|      uint col = i & 31u;
83|      Xs[i] = (row == 0u) ? (float)xv[kt + col] : 0.0f;
84|    }
85|    for (uint i = lane; i < 1024u; i += 32u) {
86|      uint k = i >> 5;
87|      uint n = i & 31u;
88|      uint kg = kt + k;
89|      float s = (float)S[kg * G + blk];
90|      float b = (float)B[kg * G + blk];
91|      uint bidx = n >> 1;
92|      uint word = W[(ulong)kg * (ulong)Ww + blk * 4u + (bidx >> 2)];
93|      uint byte = (word >> ((bidx & 3u) * 8u)) & 0xffu;
