100|      simdgroup_matrix<float, 8, 8> A;
101|      simdgroup_load(A, Xs + kk * 8u, 32);
102|      for (uint j = 0; j < 4u; ++j) {
103|        simdgroup_matrix<float, 8, 8> Bm;
104|        simdgroup_load(Bm, Ws + kk * 256u + j * 8u, 32);
