#pragma clang loop unroll(full)
  for (uint j = 0; j < 32u; ++j) {
    p[j] = simd_sum(p[j]);
  }
}

inline float qmm_accum(
    const device uint* W,
    const device bfloat* S,
    const device bfloat* B,
    const threadgroup bfloat* xv,
    uint K,
    uint G,
    uint Ww,
    uint g,
    uint wb,
    uint lane) {
  uint word = wb + (lane >> 3u);
  uint shift = (lane & 7u) * 4u;
  float acc = 0.0f;
