v_order\n18|\n19|\n20|def _scatter_unsort(x, inv_order, shape=None):\n21|    x = x[inv_order]\n22|    if shape is not None:\n23|        x = mx.unflatten(x, 0, shape)\n24|    return x\n25|\n26|\n27|class QuantizedSwitchLinear(nn.Module):\n28|    def __init__(\n29|        self,\n30|        input_dims: int,\n31|        output_dims: int,\n32|        num_experts: int,\n33|        bias: bool = True,\n34|        group_size: int = 64,\n35|        bits: int = 4,\n36|        mode: str = \"affine\",\n37|    ):\n38|        super().__init__()\n39|\n40|        scale = math.sqrt(1 / input_dims)\n41|        self.weight, self.scales, *biases = mx.quantize(\n42|            mx.random.uniform(\n43|                low=-scale,\n44|                high=scale,\n45|                shape=(num_experts, output_dims, input_dims),\n46|            ),\n47|            group_size=group_size,\n48|            bits=bits,\n49|            mode=mode,\n50|        )\n51|        self.biases = biases[0] if biases else None\n52|\n53|        if bias:\n54|            self.bias = mx.zeros((num_experts, output_dims))\n55|\n56|        self.group_size = group_size\n57|        self.bits = bits\n58|        self.mode = mode\n59|\n60|        # Freeze this model's parameters\n61|        self.freeze()\n62|\n63|    @property\n64|    def input_dims(self):\n65|        return self.scales.shape[2] * self.group_size\n66|\n67|    @property\n68|    def output_dims(self):\n69|        return self.weight.shape[1]\n70|\n71|    @property\n72|    def num_experts(self):\n73|        return self.weight.shape[0]\n74|\n75|    def __call__(self, x, indices, sorted_indices=False):\n76|        x = mx.gather_qmm(\n77|            x,\n78|            self[\"weight\"],\n79|            self[\"scales\"],\n80|            self.get(\"biases\"),\n81|            rhs_indices=indices,\n82|            transpose=True,\n83|            group_size=self.group_size,\n84|            bits=self.bits,\n85|            mode=self.mode,\n86|            sorted_indices=sorted_indices,\n87|        )\n88|        if \"bias\" in self:\n89|            x = x + mx.expand_dims(self[\"bias\"][indices], -2)\n90|        return x\n91|\n92|\n93|class SwitchLinear(nn.Module):\n94|    def __init__(\n95|        self, input_dims: int, output_dims: int, num_experts: int, bias: bool = True\n96|    ):\n97|        super().__init__()\n98|        scale = math.sqrt(1 / input_dims)\n99|        self.weight = mx.random.uniform(\n100|            low=-scale,\n101|            high=scale,\n102|            shape=(num_experts, output_dims, input_dims),\n103|        )\n104|\n105|        if bias:\n106|            self.bias = mx.zeros((num_experts, output_dims))\n107|\n108|    @property\n109|    def input_dims(self):\n110|        return self.weight.shape[2]\n111|\n112|    @property\n113|    def output_dims(self):\n114|        return self.weight.shape[1]\n115|\n116|    @property\n117|    def num_experts(self):\n118|        return self.weight.shape[0]\n119|\n120|    def __call__(self, x, indices, sorted_indices=False):\n121|        x = mx.gather_mm(\n122|            x,\n123|            self[\"weight\"].swapaxes(-1, -2),\n124|            rhs_indices=indices,\n125|            sorted_indices=sorted_indices,\n126|        )\n127|        if \"bias\" in self:\n128|            x = x + mx.expand_dims(self[\"bias\"][indices], -2)\n129|        return x\n130|\n131|    def to_quantized(self, group_size: int = 64, bits: int = 4, mode: str = \"affine\"):\n132|        num_experts, output_dims, input_dims = self.weight.shape\n133|        ql = QuantizedSwitchLinear(\n134|            input_dims,\n135|            output_dims,\n136|            num_experts,\n137|            False,\n138|            group_size,\n139|            bits,\n140|            mode=mode,\n141|        )\n142|        ql.weight, ql.scales, *biases = mx.quantize(\n143|            self.weight, group_size, bits, mode=mode\n144|        )\n145|        ql.biases = biases[0] if biases else None\n146|\n147|        if \"bias\" in self:\n148|            ql.bias = self.bias\n149|        return ql\n150|\n151|\n152|class SwiGLU(nn.Module):\n153|    def __init__(self):\n154|        super().__init__()\n155|\n156|    def __call__(self, x, gate):\n157|        return swiglu(gate, x)\n158|\n159|\n160|class SwitchGLU(nn.Module):\n161|    def __init__(\n162|        self,\n163|        input_dims: int,\n164|        hidden_dims: int,\n165|        num_experts: int,\n166|        activation=SwiGLU(),\n167|        bias: bool = False,\n168|    ):\n169|        super().__init__()\n170|\n171|        self.gate_proj = SwitchLinear(input_dims, hidden_dims, num_experts, bias=bias)\n172|        self.up_proj = SwitchLinear(input_dims, hidden_dims, num_experts, bias=bias)\n173|        self.down_proj = SwitchLinear(hidden_dims, input_dims, num_experts, bias=bias)\n174|        self.activation = activation\n175|\n176|    def __call__(self, x, indices) -> mx.array:\n177|        x = mx.expand_dims(x, (-2, -3))\n178|\n179|        # When we have many tokens, then sort them to make sure that the access\n180|        # of different experts is in order.\n181|        do_sort = indices.size >= 64\n182|        idx = indices\n183|        inv_order = None\n184|        if do_sort:\n185|            x, idx, inv_order = _gather_sort(x, indices)\n186|        if self.training:\n187|            idx = mx.stop_gradient(idx)\n188|        x_up = self.up_proj(x, idx, sorted_indices=do_sort)\n189|        x_gate = self.gate_proj(x, idx, sorted_indices=do_sort)\n190|        x = self.down_proj(\n191|            self.activation(x_up, x_gate),\n192|            idx,\n193|            sorted_indices=do_sort,\n194|        )\n195|\n196|        if do_sort:\n197|            x = _scatter_unsort(x, inv_order, indices.shape)\n198|\n199|        return x.squeeze(-2)\n200|\n201|\n202|class SwitchMLP(nn.Module):\n203|    def __init__(\n204|        self,\n205|        input_dims: int,\n206|        hidden_dims: int,\n207|        num_experts: int,\n208|        activation=nn.GELU(approx=\"precise\"),\n209|        bias: bool = False,\n210|    ):\n211|        super().__init__()\n212|\n213|        self.fc1 = SwitchLinear(input_dims, hidden_dims, num_experts, bias=bias)\n214|        self.fc2 = SwitchLinear(hidden_dims, input_dims, num_experts, bias=bias)\n215|        self.activation = activation\n216|\n217|    def __call__(self, x, indices) -> mx.array:\n218|        x = mx.expand_dims(x, (-2, -3))\n219|\n220|        # When we have many tokens, then sort them to make sure that the access\n221|        # of different experts is in order.\n222|        do_sort = indices.size >= 64\n223|        idx = indices\n224|        inv_order = None\n225|        if do_sort:\n226|            x, idx, inv_order = _gather_sort(x, indices)\n227|        if self.training:\n228|            idx = mx.stop_gradient(idx)\n229|        x = self.fc1(x, idx, sorted_indices=do_sort)\n230|        x = self.activation(x)\n231|        x = self.fc2(x, idx, sorted_indices=do_sort)\n232|\n233|        if do_sort:\n234|            x = _scatter_unsort(x, inv_order, indices.shape)\n235|\n236|        return x.squeeze(-2)"}, {"tool_call_id": "call_01a1a2b8a68976fd80a46a9b6b3fc1d3", "text": "Read text file `claude/muse-agent-brief.md`.\n1|# Brief for the Muse Spark agent: write a faster MobileMoE-S decode kernel\n2|\n3|*Written by Claude Code (Claude Opus 5.5), directed by surucuonur. Committed and tagged `agent-era` before the Muse Spark session started. [Who made what](../PROVENANCE.md).*\n4|\n5|You are a Claude Code session powered by Meta's Muse Spark, working in your own git worktree on the branch `muse-agent`. This brief fixes your task, what you may change, where your work goes and how it is judged. It does not change during your session.\n6|\n7|## The task\n8|\n9|Meta's MobileMoE-S, int4, is served on an Apple M1 Pro (16-core GPU, 200 GB/s, 16 GB) by vLLM through vllm-metal, which runs the model with MLX. The findings below measure where each decode step's time goes. A step is about 870–1,090 small GPU kernels and is far from both the bandwidth and compute limits. The findings name the pieces that cost the most.\n10|\n11|1. **Choose.** Read the findings and choose one or two of the slots below to replace with your own fused Metal kernels. Write `muse-spark/strategy.md`: why, your design, and what each saves per step at 1 and 32 requests (your estimate). End it with the JSON block described under *Your files*. Commit it.\n12|2. **Write and check.** For each chosen slot, write the kernels as files, run the grader on them, read its verdict, and improve. Up to **5 attempts per slot**; an attempt is a folder you graded and committed.\n13|3. **Finish.** Write `muse-spark/summary.md`: your final attempt per slot and what you learned. Commit it.\n14|\n15|**Read these first** (all in your worktree):\n16|- `claude/findings/bottleneck-explained.md` and `claude/findings/step-breakdown.md`: the measured findings;\n17|- `results/runs/2026-11-01-breakdown/tables.md` and `results/runs/2026-11-02-gpu-counters/tables.md`: the raw tables;\n18|- `third_party/mlx-lm/mlx_lm/models/mobilemoe.py` and `switch_layers.py`: the model code;\n19|- MLX's custom-kernel documentation: `.venv/bin/python -c \"import mlx.core as mx; help(mx.fast.metal_kernel)\"`;\n20|- `bench/grader/check_candidate.py` and `bench/grader/slots.py`: how you are graded.\n21|\n22|## The slots\n23|\n24|Each slot is a piece of the mixture-of-experts block, `MoE.__call__` in `mobilemoe.py`, which runs in all 20 layers of every step. `rows` is the number of tokens in the step: 1 to 32 in decode. The grader flattens the inputs to the shapes below and restores the model's shapes afterwards. All arrays are row-contiguous.\n25|\n26|The model's constants: hidden size `D = 768`, experts `E = 60`, experts per token `K = 4`, expert hidden size `H = 384`, `routed_scaling_factor = 2.5`, `norm_topk_prob = true`.\n27|\n28|### `routing`: router, top-4 selection and weights\n29|\n30|| | Name | Shape | Dtype |\n31||---|---|---|---|\n32|| input | `x` | [rows, 768] | bfloat16 |\n33|| input | `w_router` | [60, 768] | float32 |\n34|| input | `bias` | [60] | float32 (the model's bfloat16 `expert_bias`, converted exactly) |\n35|| output | `inds` | [rows, 4] | uint32 |\n36|| output | `weights` | [rows, 4] | float32 |\n37|\n38|Reference:\n39|\n40|```python\n41|scores = mx.sigmoid(x.astype(mx.float32) @ w_router.T)          # [rows, 60]\n42|inds = mx.argpartition(-(scores + bias), kth=3, axis=-1)[:, :4]  # the 4 largest biased scores\n43|w = mx.take_along_axis(scores, inds, axis=-1)                    # unbiased scores of those 4\n44|weights = w / (w.sum(axis=-1, keepdims=True) + 1e-20) * 2.5\n45|```\n46|\n47|The order of the 4 experts within a row is free, as long as `weights[r, j]` belongs to `inds[r, j]`. Today this slot is about 12 kernels per layer, 240 per step. It costs 1.02 ms of a 4.75 ms step at 1 request and 1.68 ms at 32 requests.\n48|\n49|### `combine`: weighting the routed experts' outputs and adding the shared expert\n50|\n51|| | Name | Shape | Dtype |\n52||---|---|---|---|\n53|| input | `y` | [rows, 4, 768] | bfloat16 (the 4 experts' outputs, in `inds` order) |\n54|| input | `weights` | [rows, 4] | float32 |\n55|| input | `shared` | [rows, 768] | bfloat16 (the shared expert's output) |\n56|| output | `out` | [rows, 768] | bfloat16 |\n57|\n58|Reference:\n59|\n60|```python\n61|out = (y * weights[..., None]).sum(axis=-2).astype(mx.bfloat16) + shared\n62|```\n63|\n64|Today this slot is 5 kernels per layer, 100 per step. It costs 0.61 ms at 1 request and 0.33 ms at 32 requests.\n65|\n66|### `routing+combine`\n67|\n68|Both slots above, each with its own kernels, in one candidate.\n69|\n70|### `experts`: the routed experts' three quantized products\n71|\n72|| | Name | Shape | Dtype |\n73||---|---|---|---|\n74|| input | `x` | [rows, 768] | bfloat16 |\n75|| input | `inds` | [rows, 4] | uint32 |\n76|| input | `gate_w`, `up_w` | [60, 768, 48] | uint32 (4-bit weights in [expert, in, out] layout, 8 per word along out) |\n77|| input | `gate_scales`, `gate_biases`, `up_scales`, `up_biases` | [60, 768, 12] | bfloat16 (one scale and bias per 32 outputs) |\n78|| input | `down_w` | [60, 384, 96] | uint32 |\n79|| input | `down_scales`, `down_biases` | [60, 384, 24] | bfloat16 |\n80|| output | `y` | [rows, 4, 768] | bfloat16 |\n81|\n82|Each weight is `w = scale * q + bias`, with `q` the 4-bit value. In MLX's affine quantization, the value for output column `o` sits in word `o / 8` at bits `4 * (o % 8)`.\n83|\n84|Reference: for each row `r` and each `j`, with `e = inds[r, j]`:\n85|\n86|```python\n87|y[r, j] = (silu(x[r] @ Wgate[e]) * (x[r] @ Wup[e])) @ Wdown[e]\n88|```\n89|\n90|As in MLX's `gather_qmm(..., transpose=False)`, each product accumulates in float32 and rounds its output to bfloat16. `silu(gate) * up` is computed on those bfloat16 values, and its result is rounded to bfloat16 before the down product.\n91|\n92|Today this slot is 7 kernels per layer at 1 request and 13 at 32 requests (from 16 rows, MLX also sorts the pairs by expert). It costs 0.92 ms at 1 request and 14.67 ms of a 28.19 ms step at 32 requests, half the step. It reads each expert once per (token, expert) pair.\n93|\n94|## Tools and limits\n95|\n96|- **Only `mx.fast.metal_kernel`, MLX 0.32.4.** You write the Metal body; MLX generates the signature. Inputs arrive as `const device T* name` and outputs as `device T* name`. Shapes and strides come as `name_shape` and `name_strides` when the source uses them. The thread attributes are available, as in MLX's documentation: `thread_position_in_grid`, `threadgroup_position_in_grid`, `thread_position_in_threadgroup`, `threads_per_threadgroup`, `simdgroup_index_in_threadgroup`, `thread_index_in_simdgroup`, and so on.\n97|- **The grader runs no Python of yours.** It reads your launch spec as data and compiles only your Metal.\n98|- **Stay within the GPU's limits.** At most 1,024 threads per threadgroup and 32 KB of threadgroup memory. A grader run should take under 3 minutes; stop one that hangs.\n99|- **Hardware.** The Apple M1 Pro GPU (`applegpu_g13s`) has 16 cores and a SIMD width of 32. bfloat16 is available in Metal as `bfloat`.\n100|\n101|## Rules of this session\n102|\n103|These keep your work apart from everyone else's. Git hooks and an audit script enforce them, and a commit that breaks them is refused.\n104|\n105|- **Write only inside `muse-spark/`.** Never change `bench/`, `claude/`, `results/`, `tools/`, `third_party/`, or any other file. A copy of the grader you edit is never used.\n106|- **Commit only on `muse-agent`,** with the co-author trailer your settings add: `Co-Authored-By: Muse Spark (Meta Model API) <muse-spark@meta-model-api.invalid>`. Start each subject with `Muse Spark:`. No other co-author.\n107|- **Never push, merge, rebase, change git config, or skip hooks.**\n108|- **Don't read `.env`** or any credentials file.\n109|- One commit per attempt, after you've run the grader on it, so the history shows every attempt in order.\n110|\n111|## Your files\n112|\n113|```\n114|muse-spark/\n115|  strategy.md                                your choice and design, ending with the targets JSON\n116|  kernels/<slot-folder>/attempt-<N>/\n117|    block-0.metal, block-1.metal, ...        Metal kernel bodies (and headers), numbered from 0\n118|    spec.json                                the launch spec\n119|    notes.md                                 optional: what you tried and why\n120|  summary.md                                 your final attempt per slot\n121|```\n122|\n123|`<slot-folder>` is `routing`, `combine`, `routing-combine` or `experts`. Grade an attempt with:\n124|\n125|```bash\n126|.venv/bin/python bench/grader/check_candidate.py muse-spark/kernels/<slot-folder>/attempt-<N> <slot>\n127|```\n128|\n129|where `<slot>` is `routing`, `combine`, `routing+combine` or `experts`.\n130|\n131|**The targets JSON** at the end of `strategy.md`:\n132|\n133|```json\n134|{\n135|  \"targets\": [\n136|    {\"slot\": \"routing+combine\", \"why\": \"...\", \"expected_saving_ms\": {\"rows_1\": 0.0, \"rows_32\": 0.0}, \"design\": \"...\"}\n137|  ]\n138|}\n139|```\n140|\n141|List one or two targets, in the order you work on them.\n142|\n143|**The launch spec** (`spec.json`):\n144|\n145|```json\n146|{\n147|  \"kernels\": [\n148|    {\n149|      \"name\": \"fused_routing\",\n150|      \"source_block\": 0,\n151|      \"header_block\": null,\n152|      \"inputs\": [\"x\", \"w_router\", \"bias\"],\n153|      \"outputs\": [\n154|        {\"name\": \"inds\", \"shape\": [\"rows\", 4], \"dtype\": \"uint32\"},\n155|        {\"name\": \"weights\", \"shape\": [\"rows\", 4], \"dtype\": \"float32\"}\n156|      ],\n157|      \"grid\": [\"rows*32\", 1, 1],\n158|      \"threadgroup\": [32, 1, 1],\n159|      \"template\": {\"T\": \"bfloat16\"},\n160|      \"init_value\": null,\n161|      \"atomic_outputs\": false\n162|    }\n163|  ],\n164|  \"slot_outputs\": {\"inds\": \"inds\", \"weights\": \"weights\"}\n165|}\n166|```\n167|\n168|- **`source_block` and `header_block`** are the numbers of your `block-N.metal` files.\n169|- **Kernels run in list order.** A kernel's `inputs` may name slot inputs or outputs of earlier kernels.\n170|- **`slot_outputs`** maps each output of the slot to the kernel output that provides it.\n171|- **For `routing+combine`,** `spec.json` holds two specs, each in the format above for its own slot: `{\"routing\": {\"kernels\": [...], \"slot_outputs\": {...}}, \"combine\": {\"kernels\": [...], \"slot_outputs\": {...}}}`. The original experts and shared expert run between the two parts. The grader tests each part on its own, and the combine part receives the reference routing weights.\n172|- **Shape and grid entries** are integers, or products of integers and the names `rows`, `D`, `E`, `K` and `H`, such as `\"rows*32\"`. Nothing else is evaluated.\n173|- **dtypes** are `float32`, `bfloat16`, `float16`, `uint32` or `int32`.\n174|- **Template values** are one of those dtypes, an integer or a boolean.\n175|- **`grid`** counts threads, not threadgroups, as in `mx.fast.metal_kernel`.\n176|\n177|## How each attempt is judged\n178|\n179|The pass criteria are the same as in the API-stage brief and were fixed before this session, as written here.\n180|\n181|1. **G1, runs.** It compiles and runs on real inputs at 1, 8 and 32 rows.\n182|2. **G2, correct.** It is tested on inputs captured from all 20 layers during a real decode step, at 1, 8 and 32 rows.\n183|   - **`routing`:** each row selects the same 4 experts. The only exception is a row whose 4th and 5th biased scores in the reference are within 1e-6 of each other; such rows are counted and reported. The weights, matched by expert, are within 1e-4 relative.\n184|   - **`combine` and `experts`:** every element is within 2 bfloat16 units in the last place of the reference value. For values smaller than 0.001 in magnitude, the unit at 0.001 applies, so summing in a different order near zero is not a failure.\n185|   - **Then, end to end:** the same greedy tokens as the original model over 24 generated tokens, at 1 and 32 requests, in both plain MLX and vLLM.\n186|3. **G3, faster.** The decode step's period is the median over 3 repeats in shuffled order, with 128-token prompts, at 1, 8 and 32 requests. It must be lower than both the original model's and an `mx.compile` of the same reference code. The gap must exceed the spread between repeats.\n187|\n188|**What the grader prints for an attempt** (JSON):\n189|- `g1` false and the compiler's error message;\n190|- or the correctness results, with counts and the worst example per check;\n191|- or, when the attempt is correct, `timing_us_per_layer`: its time per call next to the original's and the compiled reference's, and `beats_compiled`.\n192|\n193|The piece timing runs the slot on all 20 layers' captured inputs and waits for the GPU once at the end. It takes the median of 30 repeats, per layer. It is a guide; G3 decides.\n194|