1|// Header for hyp-1-experts-exact hardening, round-2 attempt-4 (builder-1-d).
2|// Builds on attempt-1 (fused single kernel, 512 threads/pair).
3|// One main change: decode gate/up interleaved via qvm_gate_up_pair below.
4|//  - qvm_block: bit-faithful replica of MLX affine_gather_qvm (unchanged
5|//    from attempt-1; still used for the down product).
6|//  - qvm_gate_up_pair: gate and up for the same 32-output block in one
7|//    K loop — both blocks' weight/scale loads issued before either
8|//    block's accumulation for that k, per-block order unchanged.
9|//  - qmm_accum: prefill (rows>=60) scalar mimic of affine_gather_qmm_rhs,
10|//    unchanged from attempt-1 (see notes.md).
11|
12|// Decode arithmetic (rows < 60): each lane accumulates its strided K
13|// elements serially in float32, dequantizing on the fly as
14|// x * (scale * q + bias), then a simd_sum tree reduces across lanes.
15|inline void qvm_block(
16|    const device uint* W,
17|    const device bfloat* S,
18|    const device bfloat* B,
19|    const threadgroup bfloat* xv,
20|    uint K,
21|    uint G,
22|    uint Ww,
23|    uint g,
24|    uint wb,
25|    uint lane,
26|    thread float* p) {
27|  for (uint j = 0; j < 32u; ++j) {
28|    p[j] = 0.0f;
29|  }
30|  for (uint k = lane; k < K; k += 32u) {
31|    float x = (float)xv[k];
32|    float scale = (float)S[k * G + g];
33|    float bias = (float)B[k * G + g];
34|    float s0 = scale;
35|    float s1 = scale / 16.0f;
36|    ulong row = (ulong)k * (ulong)Ww + (ulong)wb;
37|    uint w4[4];
38|    for (uint j = 0; j < 4u; ++j) {
39|      w4[j] = W[row + j];
40|    }
41|    for (uint i = 0; i < 16u; ++i) {
42|      uint by = (w4[i >> 2] >> ((i & 3u) * 8u)) & 0xffu;
43|      p[2u * i] += x * (s0 * (float)(by & 0x0fu) + bias);
44|      p[2u * i + 1u] += x * (s1 * (float)(by & 0xf0u) + bias);
45|    }
46|  }
47|#pragma clang loop unroll(full)
48|  for (uint j = 0; j < 32u; ++j) {
49|    p[j] = simd_sum(p[j]);
50|  }
51|}
52|
53|// Decode gate/up pair (rows < 60): same per-block arithmetic as two
54|// qvm_block calls for block g, interleaved. For each strided k the
55|// gate and up weight words, scales and biases are all loaded before
56|// either block accumulates, so the two blocks' load latencies overlap.
57|// Each block's adds still run in qvm_block's order — k = lane,
58|// lane+32, ... serial, same x*(s*q+bias) terms in the same sequence
59|// per output — pg and pu are separate accumulators, and each gets
60|// the same simd_sum tree afterwards, so every block's bits are
61|// identical to the sequential pair of qvm_block calls.
62|inline void qvm_gate_up_pair(
63|    const device uint* Wg,
64|    const device bfloat* Sg,
65|    const device bfloat* Bg,
66|    const device uint* Wu,
67|    const device bfloat* Su,
68|    const device bfloat* Bu,
69|    const threadgroup bfloat* xv,
70|    uint K,
71|    uint G,
72|    uint Ww,
73|    uint g,
74|    uint wb,
75|    uint lane,
76|    thread float* pg,
77|    thread float* pu) {
78|  for (uint j = 0; j < 32u; ++j) {
79|    pg[j] = 0.0f;
80|    pu[j] = 0.0f;
81|  }
82|  for (uint k = lane; k < K; k += 32u) {
83|    float x = (float)xv[k];
84|    float scale_g = (float)Sg[k * G + g];
85|    float bias_g = (float)Bg[k * G + g];
86|    float s0g = scale_g;
87|    float s1g = scale_g / 16.0f;
88|    ulong row_g = (ulong)k * (ulong)Ww + (ulong)wb;
89|    uint w4g[4];
90|    for (uint j = 0; j < 4u; ++j) {
91|      w4g[j] = Wg[row_g + j];
92|    }
93|    float scale_u = (float)Su[k * G + g];
94|    float bias_u = (float)Bu[k * G + g];
95|    float s0u = scale_u;
96|    float s1u = scale_u / 16.0f;
97|    ulong row_u = (ulong)k * (ulong)Ww + (ulong)wb;
98|    uint w4u[4];
99|    for (uint j = 0; j < 4u; ++j) {
100|      w4u[j] = Wu[row_u + j];
101|    }
102|    for (uint i = 0; i < 16u; ++i) {
103|      uint by = (w4g[i >> 2] >> ((i & 3u) * 8u)) & 0xffu;
104|      pg[2u * i] += x * (s0g * (float)(by & 0x0fu) + bias_g);
105|      pg[2u * i + 1u] += x * (s1g * (float)(by & 0xf0u) + bias_g);
106|    }
107|    for (uint i = 0; i < 16u; ++i) {
108|      uint by = (w4u[i >> 2] >> ((i & 3u) * 8u)) & 0xffu;
109|      pu[2u * i] += x * (s0u * (float)(by & 0x0fu) + bias_u);
110|      pu[2u * i + 1u] += x * (s1u * (float)(by & 0xf0u) + bias_u);
111|    }
112|  }
113|#pragma clang loop unroll(full)
114|  for (uint j = 0; j < 32u; ++j) {
115|    pg[j] = simd_sum(pg[j]);
116|  }
117|#pragma clang loop unroll(full)
118|  for (uint j = 0; j < 32u; ++j) {
119|    pu[j] = simd_sum(pu[j]);
120|  }
121|}
122|
123|// Prefill arithmetic (rows >= 60): one output (lane-th of the 32-output
124|// block g), accumulated by a single thread so the add order is exactly
125|// the contiguous K order, tile by tile (BK=32), mimicking BlockMMA's
126|// sequential tile order. The weight is rounded to bfloat16 before the
127|// multiply, as QuantizedBlockLoader/dequantize does into Ws:
128|//   w = bfloat(float(scale) * q + float(bias))
129|// (MLX writes the odd nibble as (s/16)*(byte&0xf0)+b; that is the same
130|// float value: scaling by powers of two is exact and s*q is exact in
131|// float32 for 4-bit q, so both forms round identically.)
132|inline float qmm_accum(
133|    const device uint* W,
134|    const device bfloat* S,
135|    const device bfloat* B,
136|    const threadgroup bfloat* xv,
137|    uint K,
138|    uint G,
139|    uint Ww,
140|    uint g,
141|    uint wb,
142|    uint lane) {
143|  uint word = wb + (lane >> 3u);
144|  uint shift = (lane & 7u) * 4u;
145|  float acc = 0.0f;
146|  for (uint tile = 0u; tile < K; tile += 32u) {
147|    for (uint kk = 0u; kk < 32u; ++kk) {
148|      uint k = tile + kk;
149|      uint w = W[(ulong)k * (ulong)Ww + (ulong)word];
150|      uint q = (w >> shift) & 0xfu;
151|      float wq = (float)S[k * G + g] * (float)q + (float)B[k * G + g];
152|      acc += (float)xv[k] * (float)(bfloat)wq;
153|    }
154|  }
155|  return acc;
156|}

