12|// Decode arithmetic (rows < 60): each lane accumulates its strided K
13|// elements serially in float32, dequantizing on the fly as
14|// x * (scale * q + bias), then a simd_sum tree reduces across lanes.
15|inline void qvm_block(
16|    const device uint* W,
17|    const device bfloat* S,
18|    const device bfloat* B,
19|    const threadgroup bfloat* xv,
20|    uint K,
21|    uint G,
22|    uint Ww,
23|    uint g,
24|    uint wb,
25|    uint lane,
26|    thread float* p) {
27|  for (uint j = 0; j < 32u; ++j) {
28|    p[j] = 0.0f;
29|  }
30|  for (uint k = lane; k < K; k += 32u) {
31|    float x = (float)xv[k];
32|    float scale = (float)S[k * G + g];
33|    float bias = (float)B[k * G + g];
34|    float s0 = scale;
35|    float s1 = scale / 16.0f;
36|    ulong row = (ulong)k * (ulong)Ww + (ulong)wb;
37|    uint w4[4];
38|    for (uint j = 0; j < 4u; ++j) {
39|      w4[j] = W[row + j];
40|    }
41|    for (uint i = 0; i < 16u; ++i) {
42|      uint by = (w4[i >> 2] >> ((i & 3u) * 8u)) & 0xffu;
43|      p[2u * i] += x * (s0 * (float)(by & 0x0fu) + bias);
44|      p[2u * i + 1u] += x * (s1 * (float)(by & 0xf0u) + bias);
45|    }
46|  }
47|#pragma clang loop unroll(full)
48|  for (uint j = 0; j < 32u; ++j) {
49|    p[j] = simd_sum(p[j]);
50|  }
51|}
