123|// Prefill arithmetic (rows >= 60): one output (lane-th of the 32-output
124|// block g), accumulated by a single thread so the add order is exactly
125|// the contiguous K order, tile by tile (BK=32), mimicking BlockMMA's
126|// sequential tile order. The weight is rounded to bfloat16 before the
127|// multiply, as QuantizedBlockLoader/dequantize does into Ws:
128|//   w = bfloat(float(scale) * q + float(bias))
129|// (MLX writes the odd nibble as (s/16)*(byte&0xf0)+b; that is the same
130|// float value: scaling by powers of two is exact and s*q is exact in
131|// float32 for 4-bit q, so both forms round identically.)
132|inline float qmm_accum(
133|    const device uint* W,
134|    const device bfloat* S,
135|    const device bfloat* B,
136|    const threadgroup bfloat* xv,
137|    uint K,
138|    uint G,
139|    uint Ww,
140|    uint g,
141|    uint wb,
142|    uint lane) {
143|  uint word = wb + (lane >> 3u);
144|  uint shift = (lane & 7u) * 4u;
145|  float acc = 0.0f;
146|  for (uint tile = 0u; tile < K; tile += 32u) {
147|    for (uint kk = 0u; kk < 32u; ++kk) {
148|      uint k = tile + kk;
149|      uint w = W[(ulong)k * (ulong)Ww + (ulong)word];
150|      uint q = (w >> shift) & 0xfu;
151|      float wq = (float)S[k * G + g] * (float)q + (float)B[k * G + g];
152|      acc += (float)xv[k] * (float)(bfloat)wq;
153|    }
154|  }
155|  return acc;
