201|// float value: scaling by powers of two is exact and s*q is exact in
202|// float32 for 4-bit q, so both forms round identically.)
203|inline float qmm_accum(
204|    const device uint* W,
205|    const device bfloat* S,
206|    const device bfloat* B,
207|    const threadgroup bfloat* xv,
208|    uint K,
209|    uint G,
210|    uint Ww,
211|    uint g,
212|    uint wb,
213|    uint lane) {
214|  uint word = wb + (lane >> 3u);
215|  uint shift = (lane & 7u) * 4u;
