60|// Decode gate/up pair (rows < 60): same per-block arithmetic as two
61|// qvm_block calls for block g, interleaved. For each strided k the
62|// gate and up weight words, scales and biases are all loaded before
63|// either block accumulates, so the two blocks' load latencies overlap.
64|// Each block's adds still run in qvm_block's order — k = lane,
65|// lane+32, ... serial, same x*(s*q+bias) terms in the same sequence
66|// per output — pg and pu are separate accumulators, and each gets
67|// the same simd_sum tree afterwards, so every block's bits are
68|// identical to the sequential pair of qvm_block calls.
69|inline void qvm_gate_up_pair(
70|    const device uint* Wg,
71|    const device bfloat* Sg,
72|    const device bfloat* Bg,
73|    const device uint* Wu,
74|    const device bfloat* Su,
75|    const device bfloat* Bu,
76|    const threadgroup bfloat* xv,
77|    uint K,
78|    uint G,
79|    uint Ww,
80|    uint g,
81|    uint wb,
82|    uint lane,
83|    thread float* pg,
84|    thread float* pu) {
85|  for (uint j = 0; j < 32u; ++j) {
86|    pg[j] = 0.0f;
87|    pu[j] = 0.0f;
88|  }
89|  for (uint k = lane; k < K; k += 32u) {
90|    float x = (float)xv[k];
91|    float scale_g = (float)Sg[k * G + g];
92|    float bias_g = (float)Bg[k * G + g];
93|    float s0g = scale_g;
94|    float s1g = scale_g / 16.0f;
95|    ulong row_g = (ulong)k * (ulong)Ww + (ulong)wb;
96|    uint w4g[4];
97|    for (uint j = 0; j < 4u; ++j) {
98|      w4g[j] = Wg[row_g + j];
99|    }
100|    float scale_u = (float)Su[k * G + g];
101|    float bias_u = (float)Bu[k * G + g];
102|    float s0u = scale_u;
103|    float s1u = scale_u / 16.0f;
104|    ulong row_u = (ulong)k * (ulong)Ww + (ulong)wb;
105|    uint w4u[4];
106|    for (uint j = 0; j < 4u; ++j) {
107|      w4u[j] = Wu[row_u + j];
108|    }
109|    for (uint i = 0; i < 16u; ++i) {
110|      uint by = (w4g[i >> 2] >> ((i & 3u) * 8u)) & 0xffu;
111|      pg[2u * i] += x * (s0g * (float)(by & 0x0fu) + bias_g);
112|      pg[2u * i + 1u] += x * (s1g * (float)(by & 0xf0u) + bias_g);
113|    }
114|    for (uint i = 0; i < 16u; ++i) {
115|      uint by = (w4u[i >> 2] >> ((i & 3u) * 8u)) & 0xffu;
116|      pu[2u * i] += x * (s0u * (float)(by & 0x0fu) + bias_u);
117|      pu[2u * i + 1u] += x * (s1u * (float)(by & 0xf0u) + bias_u);
118|    }
119|  }
120|#pragma clang loop unroll(full)
121|  for (uint j = 0; j < 32u; ++j) {
122|    pg[j] = simd_sum(pg[j]);
123|  }
124|#pragma clang loop unroll(full)
125|  for (uint j = 0; j < 32u; ++j) {
126|    pu[j] = simd_sum(pu[j]);
127|  }
128|}
