130|// Decode down pair (rows < 60): two down blocks g0/g1 in one K loop,
131|// mirroring qvm_gate_up_pair. For each strided k both blocks' weight
132|// words, scales and biases are loaded before either block accumulates,
133|// into separate accumulators p0/p1. Each block keeps qvm_block's exact
134|// order — k = lane, lane+32, ... serial, same x*(s*q+bias) terms in the
135|// same per-output sequence — and the same simd_sum tree afterwards, so
136|// every block's bits are identical to two sequential qvm_block calls.
137|inline void qvm_down_pair(
138|    const device uint* W,
139|    const device bfloat* S,
140|    const device bfloat* B,
141|    const threadgroup bfloat* xv,
142|    uint K,
143|    uint G,
144|    uint Ww,
145|    uint g0,
146|    uint wb0,
147|    uint g1,
148|    uint wb1,
149|    uint lane,
150|    thread float* p0,
151|    thread float* p1) {
152|  for (uint j = 0; j < 32u; ++j) {
153|    p0[j] = 0.0f;
154|    p1[j] = 0.0f;
155|  }
156|  for (uint k = lane; k < K; k += 32u) {
157|    float x = (float)xv[k];
158|    float scale0 = (float)S[k * G + g0];
159|    float bias0 = (float)B[k * G + g0];
160|    float s00 = scale0;
161|    float s10 = scale0 / 16.0f;
162|    ulong row0 = (ulong)k * (ulong)Ww + (ulong)wb0;
163|    uint w40[4];
164|    for (uint j = 0; j < 4u; ++j) {
165|      w40[j] = W[row0 + j];
166|    }
167|    float scale1 = (float)S[k * G + g1];
168|    float bias1 = (float)B[k * G + g1];
169|    float s01 = scale1;
170|    float s11 = scale1 / 16.0f;
171|    ulong row1 = (ulong)k * (ulong)Ww + (ulong)wb1;
172|    uint w41[4];
173|    for (uint j = 0; j < 4u; ++j) {
174|      w41[j] = W[row1 + j];
175|    }
176|    for (uint i = 0; i < 16u; ++i) {
177|      uint by = (w40[i >> 2] >> ((i & 3u) * 8u)) & 0xffu;
178|      p0[2u * i] += x * (s00 * (float)(by & 0x0fu) + bias0);
179|      p0[2u * i + 1u] += x * (s10 * (float)(by & 0xf0u) + bias0);
180|    }
181|    for (uint i = 0; i < 16u; ++i) {
182|      uint by = (w41[i >> 2] >> ((i & 3u) * 8u)) & 0xffu;
183|      p1[2u * i] += x * (s01 * (float)(by & 0x0fu) + bias1);
184|      p1[2u * i + 1u] += x * (s11 * (float)(by & 0xf0u) + bias1);
185|    }
186|  }
187|#pragma clang loop unroll(full)
188|  for (uint j = 0; j < 32u; ++j) {
189|    p0[j] = simd_sum(p0[j]);
190|  }
191|#pragma clang loop unroll(full)
192|  for (uint j = 0; j < 32u; ++j) {
193|    p1[j] = simd_sum(p1[j]);
194|  }
